# Parity-based pattern:
# even-even and odd-odd → 6
# even-odd and odd-even → 3
# straights (row 5 or col 5) → 4

output = []
for r in range(11):
    row = []
    for c in range(11):
        if r == 5 or c == 5:
            row.append(4)
        elif (r % 2 == 0 and c % 2 == 0) or (r % 2 != 0 and c % 2 != 0):
            row.append(6)
        else:
            row.append(3)
    output.append(row)

print("Parity-based output:")
for i, row in enumerate(output):
    print(f"Row {i}: {' '.join(map(str, row))}")

{"action": "submit", "grid": output}

