# Simpler checkerboard: always same pattern per row
# Even rows: 6 6 6 6 6 | 4 | 6 6 6 6 6
# Odd rows: 6 3 6 3 6 | 4 | 6 3 6 3 6
# OR simpler: always 6 except straights

output = []
for r in range(11):
    row = []
    for c in range(11):
        if r == 5 or c == 5:
            row.append(4)  # Straight
        elif (r + c) % 4 < 3:
            row.append(6)  # Fill with 6 based on (r+c) mod 4
        else:
            row.append(0)  # Fill with 0
    output.append(row)

print("Four-pattern checkerboard:")
for i, row in enumerate(output):
    print(f"Row {i}: {' '.join(map(str, row))}")

{"action": "submit", "grid": output}

